// Helper to compute automatic vendor rating (1-5 stars) from performance stats
function computeAutoRating(completedUnits = 0, rejectedUnits = 0, totalUnits = 0) {
  const safeCompleted = Math.max(0, Number(completedUnits) || 0);
  const safeRejected = Math.max(0, Number(rejectedUnits) || 0);
  const safeTotal = Math.max(0, Number(totalUnits) || 0);
  const effectiveTotal = safeTotal > 0 ? safeTotal : (safeCompleted + safeRejected);

  let quality = 1;
  if (effectiveTotal > 0) {
    const completionRate = safeCompleted / effectiveTotal; // 0..1
    const rejectionRate = safeRejected / effectiveTotal;  // 0..1
    // Score weights: prioritize completion, penalize rejections
    const score = (completionRate * 100) - (rejectionRate * 150);
    // Map score to stars
    // >= 90 => 5, >= 80 => 4, >= 65 => 3, >= 50 => 2, else 1
    let stars = 1;
    if (score >= 90) stars = 5;
    else if (score >= 80) stars = 4;
    else if (score >= 65) stars = 3;
    else if (score >= 50) stars = 2;
    quality = stars;
    return { rating: quality, score };
  }
  return { rating: quality, score: 0 };
}

