// Enhanced Service Layer with Better Error Handling
class MaterialTrackingService {
  static async updateCompletion(poId, itemIndex, operation, completedQuantity, currentUser, notes = '') {
    if (!poId || itemIndex == null || !operation || completedQuantity <= 0) {
      throw new Error('Invalid input parameters');
    }

    try {
      const poRef = doc(db, 'purchaseOrders', poId);
      
      return await runTransaction(db, async (transaction) => {
        const poDoc = await transaction.get(poRef);
        if (!poDoc.exists()) {
          throw new Error('Purchase order not found');
        }

        const poData = poDoc.data();
        const items = poData.items || [];
        
        if (!items[itemIndex]) {
          throw new Error('Item not found');
        }

        const item = items[itemIndex];
        const operationKey = `${itemIndex}_${operation}`;
        
        const materialTracking = { ...(poData.materialTracking || {}) };
        
        if (!materialTracking[operationKey]) {
          materialTracking[operationKey] = this.initializeMaterialTrack(item);
        }

        const materialTrack = materialTracking[operationKey];
        const newCompletedQuantity = Math.min(materialTrack.remainingQuantity, completedQuantity);

        if (newCompletedQuantity <= 0) {
          throw new Error('No remaining quantity to complete');
        }

        this.updateMaterialQuantities(materialTrack, newCompletedQuantity, 0, 0);
        this.addHistoryEntry(materialTrack, 'completion', newCompletedQuantity, currentUser, notes);

        // Update PO material tracking
        transaction.update(poRef, {
          materialTracking,
          updatedAt: serverTimestamp()
        });

        // Auto-update vendor performance/rating
        const vendorId = poData.vendorId;
        if (vendorId) {
          const vendorRef = doc(db, 'vendors', vendorId);
          const vendorSnap = await transaction.get(vendorRef);
          const perf = vendorSnap.exists() ? (vendorSnap.data().performance || {}) : {};
          const completedUnits = (perf.completedUnits || 0) + newCompletedQuantity;
          const rejectedUnits = perf.rejectedUnits || 0;
          const totalUnits = (perf.totalUnits || 0) + newCompletedQuantity;
          const { rating, score } = computeAutoRating(completedUnits, rejectedUnits, totalUnits);

          transaction.set(vendorRef, {
            performance: {
              completedUnits,
              rejectedUnits,
              totalUnits,
              completionRate: totalUnits > 0 ? (completedUnits / totalUnits) * 100 : 0,
              ratingAuto: rating,
              ratingScore: score,
              updatedAt: serverTimestamp()
            }
          }, { merge: true });
        }

        return {
          success: true,
          completedQuantity: newCompletedQuantity,
          totalCompleted: materialTrack.completedQuantity,
          remaining: materialTrack.remainingQuantity
        };
      });

    } catch (error) {
      console.error('Error updating material completion:', error);
      throw error;
    }
  }

  static async updateRejection(poId, itemIndex, operation, rejectedQuantity, reason, currentUser) {
    if (!poId || itemIndex == null || !operation || rejectedQuantity <= 0 || !reason?.trim()) {
      throw new Error('Invalid input parameters');
    }

    try {
      const poRef = doc(db, 'purchaseOrders', poId);
      
      return await runTransaction(db, async (transaction) => {
        const poDoc = await transaction.get(poRef);
        if (!poDoc.exists()) {
          throw new Error('Purchase order not found');
        }

        const poData = poDoc.data();
        const operationKey = `${itemIndex}_${operation}`;
        const materialTracking = { ...(poData.materialTracking || {}) };
        
        if (!materialTracking[operationKey]) {
          const item = (poData.items || [])[itemIndex];
          if (!item) {
            throw new Error('Item not found');
          }
          materialTracking[operationKey] = this.initializeMaterialTrack(item);
        }

        const materialTrack = materialTracking[operationKey];
        
        if (rejectedQuantity > materialTrack.remainingQuantity) {
          throw new Error('Rejected quantity exceeds remaining quantity');
        }

        this.updateMaterialQuantities(materialTrack, 0, rejectedQuantity, 0);
        this.addHistoryEntry(materialTrack, 'rejection', rejectedQuantity, currentUser, '', reason);

        // Update PO material tracking
        transaction.update(poRef, {
          materialTracking,
          updatedAt: serverTimestamp()
        });

        // Auto-update vendor performance/rating
        const vendorId = poData.vendorId;
        if (vendorId) {
          const vendorRef = doc(db, 'vendors', vendorId);
          const vendorSnap = await transaction.get(vendorRef);
          const perf = vendorSnap.exists() ? (vendorSnap.data().performance || {}) : {};
          const completedUnits = perf.completedUnits || 0;
          const rejectedUnits = (perf.rejectedUnits || 0) + rejectedQuantity;
          const totalUnits = (perf.totalUnits || 0) + rejectedQuantity;
          const { rating, score } = computeAutoRating(completedUnits, rejectedUnits, totalUnits);

          transaction.set(vendorRef, {
            performance: {
              completedUnits,
              rejectedUnits,
              totalUnits,
              completionRate: totalUnits > 0 ? (completedUnits / totalUnits) * 100 : 0,
              ratingAuto: rating,
              ratingScore: score,
              updatedAt: serverTimestamp()
            }
          }, { merge: true });
        }

        return {
          success: true,
          rejectedQuantity,
          totalRejected: materialTrack.rejectedQuantity,
          remaining: materialTrack.remainingQuantity
        };
      });

    } catch (error) {
      console.error('Error updating material rejection:', error);
      throw error;
    }
  }

  static initializeMaterialTrack(item) {
    return {
      totalQuantity: item.quantity || 0,
      completedQuantity: 0,
      rejectedQuantity: 0,
      scrappedQuantity: 0,
      remainingQuantity: item.quantity || 0,
      completionRate: 0,
      status: 'pending',
      lastUpdated: serverTimestamp(),
      history: []
    };
  }

  static updateMaterialQuantities(track, completed = 0, rejected = 0, scrapped = 0) {
    track.completedQuantity += completed;
    track.rejectedQuantity += rejected;
    track.scrappedQuantity += scrapped;
    
    track.remainingQuantity = track.totalQuantity - track.completedQuantity - track.rejectedQuantity - track.scrappedQuantity;
    track.completionRate = (track.completedQuantity / track.totalQuantity) * 100;
    
    // Update status based on completion
    if (track.completedQuantity >= track.totalQuantity) {
      track.status = 'completed';
    } else if (track.completedQuantity > 0) {
      track.status = track.remainingQuantity > 0 ? 'partial' : 'completed';
    } else if (track.rejectedQuantity > 0) {
      track.status = 'rejected';
    } else {
      track.status = 'pending';
    }

    track.lastUpdated = serverTimestamp();
  }

  static addHistoryEntry(track, type, quantity, user, notes = '', reason = '') {
    const historyEntry = {
      timestamp: Date.now(),
      type,
      quantity,
      totalCompleted: track.completedQuantity,
      totalRejected: track.rejectedQuantity,
      remaining: track.remainingQuantity,
      completionRate: track.completionRate,
      updatedBy: {
        uid: user?.uid,
        name: user?.displayName || 'System',
        email: user?.email,
        role: user?.vendorProfile ? 'vendor' : 'admin'
      },
      notes: notes || `${type === 'completion' ? 'Completed' : 'Rejected'} ${quantity} units`,
      reason
    };

    track.history = [historyEntry, ...(track.history || []).slice(0, 49)];
  }
}

class TaskAutomationService {
  static async createPostProcessingTask(operationData, currentUser, notes = '') {
    try {
      const taskData = {
        title: `Post-Processing: ${OPERATIONS_CONFIG[operationData.operation]?.name || operationData.operation}`,
        description: `Automatic task generated for completed PO operation. PO: ${operationData.poNumber}, Item: ${operationData.itemDescription}. ${notes ? `Notes: ${notes}` : ''}`,
        category: 'quality',
        department: 'quality-control',
        taskType: 'operation_completion',
        pickupRequired: true,
        pickupStatus: 'pending',
        pickupHistory: [],
        dueDate: new Date(Date.now() + 24 * 60 * 60 * 1000),
        estimatedTime: 60,
        status: 'pending',
        completed: false,
        progress: 0,
        sequence: [
          { step: 'Quality inspection of machined part', completed: false },
          { step: 'Documentation and certification', completed: false },
          { step: 'Prepare for next production stage', completed: false }
        ],
        sourcePO: operationData.poNumber || '',
        sourcePONumber: operationData.poNumber || '',
        sourceOperation: operationData.operation || '',
        sourceItemIndex: typeof operationData.itemIndex === 'number' ? operationData.itemIndex : 0,
        sourceItemDescription: operationData.itemDescription || '',
        sourceVendor: operationData.vendorId || '',
        sourceVendorName: operationData.vendorName || '',
        sourceQuantity: typeof operationData.quantity === 'number' ? operationData.quantity : 0,
        sourceUnit: operationData.unit || 'pcs',
        sourceSpecifications: operationData.specifications || '',
        sourceMaterial: operationData.material || '',
        operationId: `${operationData.poId || ''}_${typeof operationData.itemIndex === 'number' ? operationData.itemIndex : 0}_${operationData.operation || ''}`,
        autoGenerated: true,
        createdAt: serverTimestamp(),
        updatedAt: serverTimestamp(),
        createdBy: {
          uid: currentUser?.uid || 'system',
          name: currentUser?.displayName || 'System Auto-Generator',
          email: currentUser?.email || 'system@company.com'
        }
      };

      // Clean undefined values
      Object.keys(taskData).forEach((key) => {
        if (taskData[key] === undefined) delete taskData[key];
      });

      const existingTaskQuery = query(
        collection(db, 'industrialTasks'),
        where('sourcePO', '==', taskData.sourcePO),
        where('sourceOperation', '==', taskData.sourceOperation),
        where('sourceItemIndex', '==', taskData.sourceItemIndex),
        limit(1)
      );
      
      const existingTasks = await getDocs(existingTaskQuery);
      
      if (existingTasks.empty) {
        const docRef = await addDoc(collection(db, 'industrialTasks'), taskData);
        return { success: true, taskId: docRef.id };
      }
      return { success: false, reason: 'Task already exists' };
    } catch (error) {
      console.error('Error creating automatic task:', error);
      throw error;
    }
  }
}

// Enhanced Custom Hook with Better Performance
const usePOStatusManager = (pageSize = 100) => {
  const [state, setState] = useState({
    pos: [],
    vendors: [],
    loading: true,
    error: null,
    connectionStatus: 'connected',
    lastVisible: null,
    hasMore: true
  });

  const { showError } = useNotification();
  const unsubscribeRef = useRef(null);
  const batchSizeRef = useRef(pageSize);

  const updateState = useCallback((updates) => {
    setState(prev => ({ ...prev, ...updates }));
  }, []);

  const processPOs = useCallback((poList) => {
    return poList.map(po => {
      const operations = [];
      const operationsStatus = {};
      const operationsMeta = {};
      const materialTracking = po.materialTracking || {};
      
      if (po.items && Array.isArray(po.items)) {
        po.items.forEach((item, itemIndex) => {
          if (item.operation) {
            const operationKey = `${itemIndex}_${item.operation}`;
            const operationData = {
              operation: item.operation,
              itemIndex,
              itemDescription: item.description || `Item ${itemIndex + 1}`,
              quantity: item.quantity || 0,
              unit: item.unit || 'pcs',
              unitPrice: item.unitPrice || 0,
              specifications: item.specifications || '',
              deliveryDate: item.deliveryDate || po.deliveryDate,
              material: item.material || '',
              tolerances: item.tolerances || '',
              estimatedHours: item.estimatedHours || 0,
              materialInfo: materialTracking[operationKey] || {
                totalQuantity: item.quantity || 0,
                completedQuantity: 0,
                rejectedQuantity: 0,
                scrappedQuantity: 0,
                remainingQuantity: item.quantity || 0,
                completionRate: 0,
                status: 'pending',
                lastUpdated: po.createdAt || serverTimestamp(),
                history: []
              }
            };
            
            operations.push(operationData);
            
            let currentStatus = 'pending';
            if (po.operationsStatus) {
              if (typeof po.operationsStatus[operationKey] === 'string') {
                currentStatus = po.operationsStatus[operationKey];
              } else if (po.operationsStatus[itemIndex]?.[item.operation]) {
                currentStatus = po.operationsStatus[itemIndex][item.operation];
              }
            }
            
            operationsStatus[operationKey] = currentStatus;
            
            const existingMeta = po.operationsMeta?.[operationKey] || {};
            operationsMeta[operationKey] = {
              createdAt: existingMeta.createdAt || po.createdAt || serverTimestamp(),
              updatedAt: existingMeta.updatedAt || po.updatedAt || po.createdAt || serverTimestamp(),
              updatedBy: existingMeta.updatedBy || { name: 'System', role: 'system' },
              ...existingMeta
            };
          }
        });
      }
      
      return {
        ...po,
        operations,
        operationsStatus,
        operationsMeta,
        materialTracking,
        totalOperations: operations.length,
        completedOperations: Object.values(operationsStatus).filter(status => status === 'completed').length,
        totalMaterialValue: operations.reduce((sum, op) => sum + (op.quantity * op.unitPrice), 0),
        completedMaterialValue: operations.reduce((sum, op) => {
          const materialInfo = materialTracking[`${op.itemIndex}_${op.operation}`];
          return sum + (materialInfo?.completedQuantity || 0) * op.unitPrice;
        }, 0)
      };
    });
  }, []);

  const fetchData = useCallback(async (loadMore = false) => {
    if (!loadMore) {
      updateState({ loading: true, error: null });
    }

    try {
      const [poList, vendorList] = await Promise.all([
        getAllPOsWithOperations(state.lastVisible, batchSizeRef.current),
        getAllVendors(),
      ]);
      
      const processedPOs = processPOs(poList || []);
      
      updateState({
        pos: loadMore ? [...state.pos, ...processedPOs] : processedPOs,
        vendors: vendorList || [],
        connectionStatus: 'connected',
        loading: false,
        lastVisible: poList && poList.length > 0 ? poList[poList.length - 1] : null,
        hasMore: poList ? poList.length >= batchSizeRef.current : false
      });
    } catch (err) {
      console.error('Failed to fetch data:', err);
      updateState({ 
        error: err.message, 
        connectionStatus: 'error',
        loading: false 
      });
      if (!loadMore) {
        showError('Failed to load operations data');
      }
    }
  }, [state.lastVisible, state.pos, updateState, processPOs, showError]);

  useEffect(() => {
    let timeoutId;

    const setupRealtimeListener = () => {
      try {
        if (unsubscribeRef.current) {
          unsubscribeRef.current();
        }

        const poQuery = query(
          collection(db, 'purchaseOrders'), 
          orderBy('createdAt', 'desc'),
          limit(100)
        );

        unsubscribeRef.current = onSnapshot(
          poQuery,
          (snapshot) => {
            updateState({ connectionStatus: 'connected' });
            
            clearTimeout(timeoutId);
            timeoutId = setTimeout(() => {
              const hasRelevantChanges = snapshot.docChanges().some(change => {
                if (change.type === 'added' || change.type === 'modified') {
                  const poData = change.doc.data();
                  return poData.operationsStatus || poData.operationsMeta || poData.materialTracking;
                }
                return true;
              });

              if (hasRelevantChanges) {
                fetchData(false);
              }
            }, 500);
          },
          (error) => {
            console.error('Real-time PO listener error:', error);
            updateState({ connectionStatus: 'error' });
            showError('Real-time updates disconnected');
          }
        );
      } catch (error) {
        console.error('Error setting up real-time listener:', error);
        updateState({ connectionStatus: 'error' });
      }
    };

    setupRealtimeListener();

    return () => {
      if (unsubscribeRef.current) {
        unsubscribeRef.current();
      }
      clearTimeout(timeoutId);
    };
  }, [fetchData, showError, updateState]);

  const loadMore = useCallback(() => {
    if (!state.loading && state.hasMore) {
      fetchData(true);
    }
  }, [state.loading, state.hasMore, fetchData]);

  const retryConnection = () => {
    updateState({ connectionStatus: 'connecting' });
    fetchData(false);
  };

  return { 
    ...state,
    loadMore,
    refetch: () => fetchData(false),
    retryConnection 
  };
};

